def verify_schema(schema_def: dict) -> list:
    """
    Verifies relational database schema invariants and detects:
    1. Missing primary keys (tables without a primary key).
    2. Unindexed foreign key columns (foreign keys without an explicitly covering index).
    3. Non-null constraint drift (discrepancies between expected/base definition and actual table definitions,
       or nullable columns where a non-null invariant is specified).

    Args:
        schema_def (dict): A dictionary representing the database schema. Expected structure:
            {
                "tables": {
                    "table_name": {
                        "columns": {
                            "col_name": {
                                "nullable": bool,
                                "type": str,
                                ...
                            }
                        },
                        "primary_key": ["col1", ...],
                        "foreign_keys": [
                            {
                                "columns": ["col1", ...],
                                "referenced_table": "other_table",
                                "referenced_columns": ["col1", ...]
                            }
                        ],
                        "indexes": [
                            ["col1", ...]  # list of indexed column order/sets
                        ]
                    }
                },
                # Optional base/expected schema for drift detection comparison
                "base_schema": { ... }
            }

    Returns:
        list of str: A list of descriptive violation/invariant error messages.
    """
    violations = []

    if not isinstance(schema_def, dict) or "tables" not in schema_def:
        return ["Invalid schema definition: missing 'tables' root key."]

    tables = schema_def.get("tables", {})
    base_schema = schema_def.get("base_schema", {})
    base_tables = base_schema.get("tables", {}) if base_schema else {}

    for table_name, table_info in tables.items():
        if not isinstance(table_info, dict):
            violations.append(f"Table '{table_name}' definition is malformed.")
            continue

        columns = table_info.get("columns", {})
        primary_key = table_info.get("primary_key", [])
        foreign_keys = table_info.get("foreign_keys", [])
        indexes = table_info.get("indexes", [])

        # 1. Detect Missing Primary Keys
        if not primary_key:
            violations.append(f"Table '{table_name}' is missing a primary key.")

        # Normalize indexes for efficient lookup (convert each index to a tuple of column names)
        normalized_indexes = set()
        for idx in indexes:
            if isinstance(idx, (list, tuple)):
                # Often, an index on prefix columns can satisfy a FK, but standard rule requires 
                # the leading columns of the index to match or contain the foreign key columns.
                # Here we track exact matches or prefix matches.
                normalized_indexes.add(tuple(idx))
                # Also support prefix matching for multi-column indexes (e.g. index on (a, b) covers FK on (a))
                for i in range(1, len(idx) + 1):
                    normalized_indexes.add(tuple(idx[:i]))

        # 2. Detect Unindexed Foreign Key Columns
        for fk in foreign_keys:
            fk_cols = fk.get("columns", [])
            if not fk_cols:
                continue

            fk_tuple = tuple(fk_cols)
            # Check if an index exists that covers the foreign key columns as a prefix
            is_indexed = fk_tuple in normalized_indexes

            # If not directly matched, check if any single/composite index starts with or covers these columns
            if not is_indexed:
                # Fallback check against individual or subset index definitions
                covered = False
                for idx in indexes:
                    if isinstance(idx, (list, tuple)) and len(idx) >= len(fk_cols):
                        if tuple(idx[:len(fk_cols)]) == fk_tuple:
                            covered = True
                            break
                if not covered:
                    violations.append(
                        f"Table '{table_name}' has an unindexed foreign key on column(s): {list(fk_cols)}."
                    )

        # 3. Detect Non-Null Constraint Drift
        # Check internal consistency and drift against base_schema if provided
        base_table_info = base_tables.get(table_name, {})
        base_columns = base_table_info.get("columns", {}) if base_table_info else {}

        for col_name, col_def in columns.items():
            if not isinstance(col_def, dict):
                continue

            is_nullable = col_def.get("nullable", True)

            # Check drift against base schema definition if it exists
            if base_columns and col_name in base_columns:
                base_col_def = base_columns[col_name]
                base_nullable = base_col_def.get("nullable", True)

                # If base was strictly NOT NULL (False) but current is nullable (True), or vice-versa
                if base_nullable != is_nullable:
                    violations.append(
                        f"Non-null constraint drift detected on '{table_name}.{col_name}': "
                        f"base schema nullable={base_nullable}, current schema nullable={is_nullable}."
                    )

            # Additional constraint invariant check: Primary key components must not be nullable
            if primary_key and col_name in primary_key and is_nullable:
                violations.append(
                    f"Constraint invariant violation: Primary key column '{table_name}.{col_name}' cannot be nullable."
                )

    return violations
